// Generates shared-api/schema.d.ts from the backend OpenAPI spec.
// Usage: npm run api:generate   (env API_DOCS_URL overrides http://localhost:8080/api/docs)
import { mkdir, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import openapiTS, { astToString } from 'openapi-typescript';

const source = process.env.API_DOCS_URL || 'http://localhost:8080/api/docs';
const output = resolve(dirname(fileURLToPath(import.meta.url)), '../shared-api/schema.d.ts');

const header = `/**
 * GENERATED FILE - do not edit by hand.
 *
 * Generated by openapi-typescript from ${source}
 * Regenerate with: npm run api:generate (env API_DOCS_URL overrides the source).
 */

`;

try {
  const ast = await openapiTS(new URL(source));
  await mkdir(dirname(output), { recursive: true });
  await writeFile(output, header + astToString(ast));
  console.log(`Wrote ${output} from ${source}`);
} catch (error) {
  console.error(`Failed to generate API types from ${source}:`, error?.message ?? error);
  process.exit(1);
}
